// Scientific equations and display coordinates
/* Notebook equations and display coordinates. SI constants match the Python sources. */
window.AstroPhysics = (() => {
    const R_SUN = 6.957e8, L_SUN = 3.828e26, SIGMA = 5.670374419e-8, AU = 1.495978707e11, TAU = 2 * Math.PI;
    const clamp = (value, minimum, maximum) => Math.max(minimum, Math.min(maximum, value));
    const colourAt = (table, fraction) => table[Math.min(table.length - 1, Math.floor(clamp(fraction, 0, 1) * table.length))];
    const rgb = colour => `rgb(${colour.map(channel => channel * 255).join(', ')})`;
    const significant = value => Number(value.toPrecision(3)).toString();

    function snap(value, minimum, maximum, step) {
        const nearest = minimum + Math.round((value - minimum) / step) * step;
        return clamp(Math.abs(maximum - value) < Math.abs(nearest - value) ? maximum : Number(nearest.toPrecision(14)), minimum, maximum);
    }

    function planetSystem(state, eccentric = false) {
        const { radius, temperature, albedo, distance, anomaly } = state;
        const eccentricity = eccentric ? state.eccentricity : 0;
        const separation = distance * (1 - eccentricity ** 2) / (1 + eccentricity * Math.cos(anomaly));
        const perihelion = distance * (1 - eccentricity), aphelion = distance * (1 + eccentricity);
        const equilibrium = temperature * Math.sqrt(radius * R_SUN / (2 * separation * AU)) * (1 - albedo) ** 0.25;
        const distanceFraction = Math.log10(distance / 0.01) / Math.log10(3000);
        const orbitA = 1.3 + 1.2 * distanceFraction;
        const starX = eccentric ? 1.8 : 1.3;
        const displayDistance = eccentric ? orbitA * (1 - eccentricity ** 2) / (1 + eccentricity * Math.cos(anomaly)) : orbitA;
        return { separation, perihelion, aphelion, equilibrium, starX, starRadius: 0.4 * radius, orbitA,
            orbitB: eccentric ? orbitA * Math.sqrt(1 - eccentricity ** 2) : 0.325 * orbitA,
            orbitCenter: starX + orbitA * eccentricity, displayDistance,
            planetX: eccentric ? starX - displayDistance * Math.cos(anomaly) : 2.6 + 1.2 * distanceFraction,
            planetY: eccentric ? displayDistance * Math.sin(anomaly) : 0,
            warning: perihelion * AU <= radius * R_SUN,
            starColour: colourAt(AstroColormaps.stellar, (temperature - 2500) / 5500),
            planetColour: colourAt(AstroColormaps.coolwarm, equilibrium / 2000) };
    }

    function meanFromTrue(anomaly, eccentricity) {
        const eccentricAnomaly = 2 * Math.atan2(Math.sqrt(1 - eccentricity) * Math.sin(anomaly / 2), Math.sqrt(1 + eccentricity) * Math.cos(anomaly / 2));
        return eccentricAnomaly - eccentricity * Math.sin(eccentricAnomaly);
    }

    function trueFromMean(mean, eccentricity) {
        mean = ((mean % TAU) + TAU) % TAU;
        let eccentricAnomaly = mean;
        for (let iteration = 0; iteration < 12; iteration++) {
            const correction = (eccentricAnomaly - eccentricity * Math.sin(eccentricAnomaly) - mean) / (1 - eccentricity * Math.cos(eccentricAnomaly));
            eccentricAnomaly -= correction;
            if (Math.abs(correction) < 1e-12) break;
        }
        const anomaly = 2 * Math.atan2(Math.sqrt(1 + eccentricity) * Math.sin(eccentricAnomaly / 2), Math.sqrt(1 - eccentricity) * Math.cos(eccentricAnomaly / 2));
        return ((anomaly % TAU) + TAU) % TAU;
    }

    function blackbodyColour(temperature) {
        const knots = AstroColormaps.blackbody;
        const upper = knots.findIndex(row => row[0] >= temperature);
        if (upper <= 0) return knots[upper === 0 ? 0 : knots.length - 1].slice(1);
        const fraction = (temperature - knots[upper - 1][0]) / (knots[upper][0] - knots[upper - 1][0]);
        return knots[upper].slice(1).map((channel, index) => knots[upper - 1][index + 1] + fraction * (channel - knots[upper - 1][index + 1]));
    }

    function blackbodySpectrum(temperature, radius = 1) {
        const h = 6.62607015e-34, c = 299792458, kB = 1.380649e-23;
        const peak = 2897.8 / temperature;
        const wavelengths = Array.from({ length: 500 }, (_, index) => 0.1 * peak + index * (4.9 * peak / 499));
        const flux = wavelengths.map(wavelength => {
            const metres = wavelength * 1e-6;
            return Math.PI * 2 * h * c ** 2 / metres ** 5 / Math.expm1(h * c / (metres * kB * temperature)) * 1e-6;
        });
        const surfaceArea = 4 * Math.PI * (radius * R_SUN) ** 2;
        const luminosity = flux.map(value => surfaceArea * value / L_SUN);
        const totalLuminosity = surfaceArea * SIGMA * temperature ** 4 / L_SUN;
        return { peak, wavelengths, flux, luminosity, totalLuminosity, colour: blackbodyColour(temperature) };
    }

    return { R_SUN, AU, TAU, clamp, snap, colourAt, rgb, significant, planetSystem, meanFromTrue, trueFromMean, blackbodyColour, blackbodySpectrum };
})();

// Shared sliders and SVG helpers
/* Small shared helpers for the two standalone SVG visualizations. */
window.AstroVisuals = (() => {
    const { clamp, snap } = AstroPhysics;
    function attributes(element, values) {
        for (const [name, value] of Object.entries(values)) element.setAttribute(name, value);
        return element;
    }
    function svgElement(tag, values, parent, text) {
        const element = attributes(document.createElementNS('http://www.w3.org/2000/svg', tag), values);
        if (text !== undefined) element.textContent = text;
        parent.append(element);
        return element;
    }
    function control(container, options, onChange) {
        const { id, label, min, max, step, value, format = String, logarithmic = false, integer = false } = options;
        const row = document.createElement('div');
        row.className = 'viz-control';
        row.innerHTML = `<div class="control-label"><label for="${id}">${label}</label><input id="${id}-value" type="number" min="${min}" max="${max}" step="any" aria-label="${label}, exact value"></div><input id="${id}" type="range" step="any"><div class="control-limits"><span>${format(min)}</span><span>${format(max)}</span></div>`;
        container.append(row);
        const slider = row.querySelector('input[type="range"]'), number = row.querySelector('input[type="number"]');
        const toSlider = logarithmic ? Math.log10 : value => value;
        const fromSlider = logarithmic ? value => 10 ** value : value => value;
        const sliderMin = toSlider(min), sliderMax = toSlider(max);
        attributes(slider, { min: sliderMin, max: sliderMax });
        let current = value;
        function setValue(next) {
            current = next;
            slider.value = toSlider(next);
            slider.setAttribute('aria-valuetext', format(next));
            number.value = Number(next.toPrecision(12));
        }
        function commitSlider(next) {
            const position = snap(next, sliderMin, sliderMax, step);
            const result = position === sliderMax ? max : position === sliderMin ? min : fromSlider(position);
            setValue(result);
            onChange(result);
        }
        slider.addEventListener('input', () => commitSlider(Number(slider.value)));
        slider.addEventListener('keydown', event => {
            const directions = { ArrowRight: 1, ArrowUp: 1, ArrowLeft: -1, ArrowDown: -1, PageUp: 10, PageDown: -10 };
            if (!(event.key in directions) && event.key !== 'Home' && event.key !== 'End') return;
            event.preventDefault();
            commitSlider(event.key === 'Home' ? sliderMin : event.key === 'End' ? sliderMax : toSlider(current) + directions[event.key] * step);
        });
        number.addEventListener('change', () => {
            if (number.value === '' || !Number.isFinite(number.valueAsNumber)) return setValue(current);
            const next = clamp(integer ? Math.round(number.valueAsNumber) : number.valueAsNumber, min, max);
            setValue(next);
            onChange(next);
        });
        setValue(value);
        return { row, slider, number, setValue, label: row.querySelector('label') };
    }
    function svgPoint(svg, event) {
        return new DOMPoint(event.clientX, event.clientY).matrixTransform(svg.getScreenCTM().inverse());
    }
    return { attributes, svgElement, control, svgPoint };
})();

// Planet equilibrium temperature: drawing, dragging, and playback
(() => {
    const { TAU, snap, rgb, significant, planetSystem, meanFromTrue, trueFromMean } = AstroPhysics;
    const { attributes, svgElement, control, svgPoint } = AstroVisuals;
    const defaults = { radius: 0.3, temperature: 3150, albedo: 0, distance: 0.02, eccentricity: 0.4, anomaly: 0 };
    let state = { ...defaults };
    const svg = document.getElementById('planet-diagram');
    const result = document.getElementById('planet-result'), status = document.getElementById('planet-status');
    const play = document.getElementById('planet-play');
    let playing = false, frame = null, lastTime = null, meanAnomaly = 0, pointer = null;
    const wholeKelvin = value => value.toLocaleString('en-US', { maximumFractionDigits: 0 });
    const options = [
        { name: 'radius', label: 'Stellar radius [R☉]', min: 0.2, max: 3, step: 0.02, format: value => value.toFixed(2) },
        { name: 'temperature', label: 'Stellar temperature [K]', min: 2500, max: 8000, step: 50, integer: true, format: wholeKelvin },
        { name: 'albedo', label: 'Bond albedo', min: 0, max: 1, step: 0.05, format: value => value.toFixed(2) },
        { name: 'distance', label: 'Semimajor axis a [AU]', min: 0.01, max: 30, step: 0.01, logarithmic: true, format: significant },
        { name: 'eccentricity', label: 'Eccentricity e', min: 0, max: 0.75, step: 0.01, format: value => value.toFixed(2) },
        { name: 'anomaly', label: 'True anomaly ν [rad]', min: 0, max: TAU, step: 0.05, format: value => value.toFixed(2) }
    ];
    const controls = {};
    for (const option of options) {
        controls[option.name] = control(document.getElementById('planet-controls'), { ...option, id: `planet-${option.name}`, value: defaults[option.name] }, value => {
            pause();
            state[option.name] = value;
            render();
        });
    }

    const starfield = svgElement('g', { class: 'orbit-starfield', 'aria-hidden': 'true', 'pointer-events': 'none' }, svg);
    for (let index = 1; index <= 100; index++) {
        svgElement('circle', { cx: (index * 0.754877666 % 1) * 800, cy: (index * 0.56984029 % 1) * 515, r: index % 9 === 0 ? 1.4 : 0.7, fill: '#fff', opacity: 0.18 + (index % 5) * 0.1 }, starfield);
    }
    const orbit = svgElement('ellipse', { fill: 'none', stroke: '#aab4c8', opacity: 0.75, 'stroke-dasharray': '6 4', 'stroke-width': 1.5 }, svg);
    const glowOuter = svgElement('circle', { opacity: 0.06 }, svg);
    const glowInner = svgElement('circle', { opacity: 0.10 }, svg);
    const photons = svgElement('g', { opacity: 0.8, 'aria-hidden': 'true' }, svg);
    const star = svgElement('circle', {}, svg);
    const planet = svgElement('circle', { r: 7, stroke: 'gray', 'stroke-width': 1.07, id: 'planet-disk' }, svg);
    const perihelionLabel = svgElement('text', { class: 'plot-text secondary-label', 'text-anchor': 'middle' }, svg, 'perihelion');
    const aphelionLabel = svgElement('text', { class: 'plot-text secondary-label', 'text-anchor': 'middle' }, svg, 'aphelion');
    const hit = svgElement('circle', { class: 'planet-hit', id: 'planet-drag', tabindex: 0, role: 'slider', 'aria-label': 'Planet position: true anomaly', 'aria-valuemin': 0, 'aria-valuemax': TAU, 'aria-describedby': 'planet-help' }, svg);

    function render() {
        const system = planetSystem(state, true);
        const x = value => (value + 1) * 100;
        const y = value => (2.5 - value) * 100;
        attributes(orbit, { cx: x(system.orbitCenter), cy: y(0), rx: 100 * system.orbitA, ry: 100 * system.orbitB });
        for (const [element, scale] of [[glowOuter, 1.7], [glowInner, 1.35], [star, 1]]) {
            attributes(element, { cx: x(system.starX), cy: y(0), r: 100 * system.starRadius * scale, fill: rgb(system.starColour) });
        }
        attributes(planet, { cx: x(system.planetX), cy: y(system.planetY), fill: rgb(system.planetColour) });
        photons.replaceChildren();
        const start = system.starRadius + 0.12, end = system.displayDistance - 0.12;
        if (system.displayDistance > system.starRadius + 0.15) {
            for (let index = 0; index < 6; index++) {
                const distance = start + index * (end - start) / 5;
                const photonX = x(system.starX + distance * (system.planetX - system.starX) / system.displayDistance);
                const photonY = y(distance * system.planetY / system.displayDistance);
                svgElement('circle', { cx: photonX, cy: photonY, r: 2.5, fill: rgb(system.starColour) }, photons);
            }
        }
        for (const [label, position] of [[perihelionLabel, system.orbitCenter - system.orbitA], [aphelionLabel, system.orbitCenter + system.orbitA]]) {
            attributes(label, { x: x(position), y: y(-0.22) + 15, visibility: state.eccentricity === 0 ? 'hidden' : 'visible' });
        }
        const screenScale = svg.getScreenCTM()?.a || 1;
        attributes(hit, { cx: x(system.planetX), cy: y(system.planetY), r: Math.max(12, 22 / screenScale), 'aria-valuenow': state.anomaly, 'aria-valuetext': `${state.anomaly.toFixed(2)} radians` });
        result.textContent = `Equilibrium temperature: ${wholeKelvin(system.equilibrium)} K`;
        document.getElementById('planet-current-distance').textContent = `${significant(system.separation)} AU`;
        document.getElementById('planet-perihelion').textContent = `${significant(system.perihelion)} AU`;
        document.getElementById('planet-aphelion').textContent = `${significant(system.aphelion)} AU`;
        status.hidden = !system.warning;
        status.classList.toggle('warning', system.warning);
        status.setAttribute('aria-live', playing ? 'off' : 'polite');
        status.textContent = system.warning ? 'Warning: perihelion lies inside the star.' : '';
        document.getElementById('planet-svg-description').textContent = `${result.textContent}. Current distance: ${significant(system.separation)} AU. Perihelion: ${significant(system.perihelion)} AU. Aphelion: ${significant(system.aphelion)} AU. ${status.textContent} Use the planet's arrow keys or the labelled controls to adjust true anomaly.`;
    }

    function pause() {
        playing = false;
        if (frame !== null) cancelAnimationFrame(frame);
        frame = null;
        lastTime = null;
        play.textContent = 'Play orbit';
        play.setAttribute('aria-pressed', 'false');
        status.setAttribute('aria-live', 'polite');
    }
    function animate(timestamp) {
        if (!playing) return;
        if (lastTime !== null) meanAnomaly += (timestamp - lastTime) / 12000 * TAU;
        lastTime = timestamp;
        state.anomaly = trueFromMean(meanAnomaly, state.eccentricity);
        controls.anomaly.setValue(state.anomaly);
        render();
        frame = requestAnimationFrame(animate);
    }
    document.getElementById('planet-reset').addEventListener('click', () => {
        pause();
        state = { ...defaults };
        for (const option of options) controls[option.name].setValue(state[option.name]);
        render();
    });
    play.addEventListener('click', () => {
        if (playing) return pause();
        playing = true;
        meanAnomaly = meanFromTrue(state.anomaly, state.eccentricity);
        play.textContent = 'Pause orbit';
        play.setAttribute('aria-pressed', 'true');
        frame = requestAnimationFrame(animate);
    });
    hit.addEventListener('pointerdown', event => {
        if (!event.isPrimary || event.button !== 0) return;
        event.preventDefault();
        pause();
        pointer = event.pointerId;
        hit.setPointerCapture(pointer);
        hit.classList.add('dragging');
        hit.focus({ preventScroll: true });
    });
    hit.addEventListener('pointermove', event => {
        if (event.pointerId !== pointer) return;
        const point = svgPoint(svg, event);
        const dx = 1.8 - (point.x / 100 - 1), dy = 2.5 - point.y / 100;
        if (Math.hypot(dx, dy) < 1e-8) return;
        state.anomaly = snap((Math.atan2(dy, dx) + TAU) % TAU, 0, TAU, 0.05);
        controls.anomaly.setValue(state.anomaly);
        render();
    });
    function release(event) {
        if (event.pointerId !== pointer) return;
        pointer = null;
        hit.classList.remove('dragging');
        if (hit.hasPointerCapture(event.pointerId)) hit.releasePointerCapture(event.pointerId);
    }
    for (const name of ['pointerup', 'pointercancel', 'lostpointercapture']) hit.addEventListener(name, release);
    hit.addEventListener('keydown', event => {
        if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'PageUp', 'PageDown', 'Home', 'End'].includes(event.key)) return;
        event.preventDefault();
        controls.anomaly.slider.dispatchEvent(new KeyboardEvent('keydown', { key: event.key }));
    });
    document.addEventListener('visibilitychange', () => { if (document.hidden) pause(); });
    matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change', event => { if (event.matches) pause(); });
    new ResizeObserver(render).observe(svg);
    render();
})();

// Blackbody spectrum: drawing and controls
(() => {
    const { blackbodySpectrum, rgb, significant } = AstroPhysics;
    const { attributes, svgElement, control } = AstroVisuals;
    const svg = document.getElementById('blackbody-diagram');
    let temperature = 5600, radius = 1;
    const temperatureControl = control(document.getElementById('blackbody-controls'), {
        id: 'blackbody-temperature', label: 'Temperature [K]', min: 200, max: 10000, step: 30, integer: true, value: temperature, format: value => `${value.toLocaleString('en-US')} K`
    }, value => {
        temperature = value;
        render();
    });
    const radiusControl = control(document.getElementById('blackbody-controls'), {
        id: 'blackbody-radius', label: 'Radius [R☉]', min: 0.01, max: 10, step: 0.01, logarithmic: true, value: radius, format: significant
    }, value => {
        radius = value;
        render();
    });
    const definitions = svgElement('defs', {}, svg);
    const clip = svgElement('clipPath', { id: 'blackbody-clip' }, definitions);
    const clipRectangle = svgElement('rect', {}, clip);
    const axes = svgElement('g', { 'aria-hidden': 'true' }, svg);
    const plot = svgElement('g', { 'clip-path': 'url(#blackbody-clip)' }, svg);
    const outline = svgElement('path', { fill: 'none', stroke: 'rgb(76.5, 76.5, 76.5)', 'stroke-width': 4.667, 'stroke-linejoin': 'round' }, plot);
    const curve = svgElement('path', { id: 'blackbody-curve', fill: 'none', 'stroke-width': 3.333, 'stroke-linejoin': 'round' }, plot);

    function ticks(minimum, maximum, count) {
        const rough = (maximum - minimum) / count;
        const power = 10 ** Math.floor(Math.log10(rough));
        const step = [1, 2, 2.5, 5, 10].find(value => value * power >= rough) * power;
        const values = [];
        for (let value = Math.ceil(minimum / step) * step; value <= maximum + step * 1e-8; value += step) values.push(value);
        return values;
    }
    function render() {
        const spectrum = blackbodySpectrum(temperature, radius);
        const width = Math.max(240, svg.clientWidth), compact = width < 450;
        const height = Math.max(300, Math.min(500, width * 0.625));
        const margin = { left: compact ? 66 : 80, right: 18, top: 32, bottom: 56 };
        const plotWidth = width - margin.left - margin.right, plotHeight = height - margin.top - margin.bottom;
        const maximumLuminosity = Math.max(...spectrum.luminosity), minimumLuminosity = Math.min(...spectrum.luminosity);
        // Matplotlib's default 5% margins on both linear axes.
        const xMin = -0.145 * spectrum.peak, xMax = 5.245 * spectrum.peak;
        const yMin = minimumLuminosity - 0.05 * (maximumLuminosity - minimumLuminosity), yMax = maximumLuminosity + 0.05 * (maximumLuminosity - minimumLuminosity);
        const x = value => margin.left + (value - xMin) / (xMax - xMin) * plotWidth;
        const y = value => margin.top + (yMax - value) / (yMax - yMin) * plotHeight;
        attributes(svg, { viewBox: `0 0 ${width} ${height}` });
        attributes(clipRectangle, { x: margin.left, y: margin.top, width: plotWidth, height: plotHeight });
        axes.replaceChildren();
        svgElement('rect', { x: margin.left, y: margin.top, width: plotWidth, height: plotHeight, fill: 'none', stroke: '#333' }, axes);
        const fontSize = compact ? 12 : 15;
        const text = (label, values) => svgElement('text', { class: 'plot-text', style: `font-size:${fontSize}px`, ...values }, axes, label);
        for (const value of ticks(xMin, xMax, compact ? 3 : 6)) {
            svgElement('line', { x1: x(value), x2: x(value), y1: height - margin.bottom, y2: height - margin.bottom + 5, stroke: '#333' }, axes);
            text(significant(value), { x: x(value), y: height - margin.bottom + 20, 'text-anchor': 'middle' });
        }
        const exponent = Math.floor(Math.log10(maximumLuminosity));
        const multiplier = exponent >= 6 || exponent <= -5 ? 10 ** exponent : 1;
        for (const value of ticks(yMin, yMax, compact ? 4 : 6)) {
            svgElement('line', { x1: margin.left - 5, x2: margin.left, y1: y(value), y2: y(value), stroke: '#333' }, axes);
            text(significant(value / multiplier), { x: margin.left - 9, y: y(value) + 4, 'text-anchor': 'end' });
        }
        if (multiplier !== 1) text(`×10${String(exponent).replace(/[-0-9]/g, character => ({ '-': '⁻', 0: '⁰', 1: '¹', 2: '²', 3: '³', 4: '⁴', 5: '⁵', 6: '⁶', 7: '⁷', 8: '⁸', 9: '⁹' })[character])}`, { x: margin.left, y: margin.top - 10 });
        text('Wavelength λ [μm]', { x: margin.left + plotWidth / 2, y: height - 12, 'text-anchor': 'middle' });
        text(compact ? 'Lλ [L☉ μm⁻¹]' : 'Spectral luminosity Lλ [L☉ μm⁻¹]', { transform: `translate(${compact ? 14 : 19} ${margin.top + plotHeight / 2}) rotate(-90)`, 'text-anchor': 'middle' });
        const path = spectrum.wavelengths.map((wavelength, index) => `${index ? 'L' : 'M'}${x(wavelength)},${y(spectrum.luminosity[index])}`).join(' ');
        outline.setAttribute('d', path);
        attributes(curve, { d: path, stroke: rgb(spectrum.colour) });
        document.getElementById('blackbody-result').textContent = `Blackbody spectrum · ${temperature.toLocaleString('en-US')} K`;
        document.getElementById('blackbody-peak').textContent = `${spectrum.peak.toFixed(2)} μm`;
        const luminosityResult = document.getElementById('blackbody-luminosity');
        if (spectrum.totalLuminosity >= 0.001 && spectrum.totalLuminosity < 1000) luminosityResult.textContent = `${significant(spectrum.totalLuminosity)} L☉`;
        else {
            const [coefficient, power] = spectrum.totalLuminosity.toExponential(2).split('e');
            luminosityResult.innerHTML = `${coefficient} × 10<sup>${Number(power)}</sup> L☉`;
        }
        document.getElementById('blackbody-svg-description').textContent = `At ${temperature} kelvin and radius ${significant(radius)} solar radii, total luminosity is ${significant(spectrum.totalLuminosity)} solar luminosities and peak wavelength is ${spectrum.peak.toFixed(2)} micrometres. Wavelength is plotted from ${significant(spectrum.wavelengths[0])} to ${significant(spectrum.wavelengths[499])} micrometres. Spectral luminosity is in solar luminosities per micrometre.`;
    }
    document.getElementById('blackbody-reset').addEventListener('click', () => {
        temperature = 5600;
        radius = 1;
        temperatureControl.setValue(temperature);
        radiusControl.setValue(radius);
        render();
    });
    new ResizeObserver(render).observe(svg);
    render();
})();
